public String getChannelUrl() {
	try {
		String rawId = getId();
		// Handle the case where id might be a full URL instead of just a channel ID.
		// This can happen if the channel ID was stored as a full URL (e.g., "https://www.youtube.com/channel/UCxxx").
		if (rawId != null && rawId.contains("youtube.com")) {
			try {
				android.net.Uri uri = android.net.Uri.parse(rawId);
				String channelPath = uri.getPathSegment(uri.getPathSegments().size() - 1);
				if (channelPath != null && channelPath.startsWith("channel/")) {
					rawId = channelPath.substring("channel/".length());
				} else if (channelPath != null) {
					// Could be a handle like "/c/ChannelName" or "/@handle"
					rawId = channelPath;
				}
			} catch (Exception e) {
				Logger.e(this, "Failed to parse channel URL, using raw id: " + rawId, e);
			}
		}
		return YoutubeChannelLinkHandlerFactory.getInstance().getUrl(rawId);
	} catch (ParsingException p) {
		Logger.e(this, "getChannel URL for " + getId() + ", error:" + p.getMessage(), p);
		return id;
	}
}

